INSERT INTO `citizenComplaints` (`reportedBy`, `region`, `neighborhood`, `description`, `latitude`, `longitude`, `status`, `dueAt`, `createdAt`) VALUES
  (1, 'Batı Bölgesi', 'Batıkent Mahallesi', 'Konteyner çevresine çok miktarda evsel atık ve poşet taşmış, sokakta koku yapıyor. (Batıkent Mahallesi)', '39.800657', '30.471415', 'açık', '2026-08-21 10:05:30', '2026-08-21 08:05:30'),
  (1, 'Batı Bölgesi', 'Çamlıca Mahallesi', 'Park kenarındaki çöp kutuları tamamen dolmuş, piknik atıkları çimlere yayılmış. (Çamlıca Mahallesi)', '39.781126', '30.474511', 'açık', '2026-08-21 13:05:30', '2026-08-21 09:05:30'),
  (1, 'Batı Bölgesi', 'Şirintepe Mahallesi', 'Sokak girişinde çöp birikintisi oluşmuş, acil süpürge aracıyla temizlik rica ediyoruz. (Şirintepe Mahallesi)', '39.805574', '30.493557', 'açık', '2026-08-21 13:05:30', '2026-08-21 10:05:30'),
  (1, 'Merkez Bölgesi', 'Uluönder Mahallesi', 'Pazar yeri sonrası kalan sebze ve poşet atıkları rüzgarda çevreye dağılıyor. (Uluönder Mahallesi)', '39.799446', '30.508278', 'açık', '2026-08-21 10:05:30', '2026-08-21 08:05:30'),
  (1, 'Batı Bölgesi', 'Ertuğrulgazi Mahallesi', 'Site önündeki çöp konteynerleri yetersiz kalıyor, ilave konteyner konulması gerek. (Ertuğrulgazi Mahallesi)', '39.77245', '30.485996', 'açık', '2026-08-21 15:05:30', '2026-08-21 09:05:30'),
  (1, 'Batı Bölgesi', 'Sazova Mahallesi', 'Apartman önüne tadilat molozları dökülmüş, araç geçişini zorlaştırıyor. (Sazova Mahallesi)', '39.770608', '30.473964', 'açık', '2026-08-21 15:05:30', '2026-08-21 10:05:30'),
  (1, 'Merkez Bölgesi', 'Yenibağlar Mahallesi', 'Konteyner arkasında çöp poşetleri patlamış, sokak hayvanları dağıtıyor. (Yenibağlar Mahallesi)', '39.792047', '30.504464', 'açık', '2026-08-21 10:05:30', '2026-08-21 08:05:30'),
  (1, 'Merkez Bölgesi', 'Bahçelievler Mahallesi', 'Ağaç budama dalları yola taşmış durumda, süpürge ekibi yönlendirilebilir mi? (Bahçelievler Mahallesi)', '39.787864', '30.521082', 'açık', '2026-08-21 13:05:30', '2026-08-21 09:05:30'),
  (1, 'Merkez Bölgesi', 'Eskibağlar Mahallesi', 'Kaldırım üzerindeki çöp yığını günlerdir alınmamış, sinek ve koku yapıyor. (Eskibağlar Mahallesi)', '39.783527', '30.511586', 'açık', '2026-08-21 11:05:30', '2026-08-21 10:05:30'),
  (1, 'Merkez Bölgesi', 'Hoşnudiye Mahallesi', 'Çöp konteynerinin kapağı açık kalmış ve koku yayılıyor, temizlenip dezenfekte edilmeli. (Hoşnudiye Mahallesi)', '39.78351', '30.515914', 'açık', '2026-08-21 11:05:30', '2026-08-21 08:05:30');
